res = requests.post(
    '{{WA_API_BASE}}/api/v1/messages',
    headers={
        'Authorization': f"Bearer {os.environ['SM_API_KEY']}",
        'Idempotency-Key': 'appt-5512-reminder',
    },
    json={
      "to": "+919812345678",
      "type": "template",
      "template": {
        "name": "appointment_reminder",
        "language": "en_US",
        "parameters": [
          {
            "text": "Asha"
          },
          {
            "text": "Dr. Mehta"
          },
          {
            "text": "12 Oct, 4:30 PM"
          }
